import React, { useState } from "react";
import api from "@landinghub/api";
import Background from "../components/Background";
import { CheckCircle2, ChevronDown } from "lucide-react";
import "../styles/Support.css";

const faqsData = [
  {
    question: "Làm sao để tạo landing page nhanh chóng?",
    answer:
      "Chọn template, kéo thả các thành phần và xuất bản. Không cần kỹ năng code."
  },
  {
    question: "Có thể tùy chỉnh layout không?",
    answer:
      "LandingHub cho phép chỉnh sửa mọi phần tử, màu sắc, font chữ và bố cục."
  },
  {
    question: "Hỗ trợ kỹ thuật như thế nào?",
    answer:
      "Chúng tôi có chat trực tuyến và form liên hệ 24/7, đảm bảo phản hồi nhanh chóng."
  }
];

const Support = () => {
  const [openIndex, setOpenIndex] = useState(null);
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    notes: ""
  });
  const [submitted, setSubmitted] = useState(false);

  const toggleFAQ = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      alert("Tên và Email là bắt buộc!");
      return;
    }
    try {
      await api.post("/api/leads", { ...form, status: "new" });
      setSubmitted(true);
      setForm({ name: "", email: "", phone: "", notes: "" });
      setTimeout(() => setSubmitted(false), 4000);
    } catch (err) {
      console.error(err);
      alert("Gửi thông tin thất bại. Vui lòng thử lại.");
    }
  };

  return (
    <Background showShapes={false} fullWidth>
      <div className="support-container">
        {/* Hero Section */}
        <section className="support-hero">
          <div className="hero-inner">
            <h1>Trung tâm Hỗ trợ LandingHub</h1>
            <p>
              Giúp bạn giải quyết vấn đề, khám phá tính năng và nhận được phản
              hồi nhanh chóng.
            </p>
          </div>
        </section>

        {/* FAQ Section */}
        <section className="faq-section">
          <h2>Câu hỏi thường gặp</h2>
          <div className="faq-list">
            {faqsData.map((faq, idx) => (
              <div
                key={idx}
                className={`faq-item ${openIndex === idx ? "open" : ""}`}
                onClick={() => toggleFAQ(idx)}
              >
                <div className="faq-header">
                  <span>{faq.question}</span>
                  <ChevronDown
                    className={`faq-icon ${
                      openIndex === idx ? "rotate" : ""
                    }`}
                    size={18}
                  />
                </div>
                <div className="faq-body">{faq.answer}</div>
              </div>
            ))}
          </div>
        </section>

        {/* Contact Form Section */}
        <section className="contact-section">
          <div className="contact-container">
            <div className="contact-info">
              <h2>Liên hệ với đội ngũ hỗ trợ</h2>
              <p>
                Chúng tôi luôn sẵn sàng giúp bạn giải quyết mọi vấn đề, từ kỹ
                thuật đến hướng dẫn sử dụng. Hãy để lại thông tin, đội ngũ của
                chúng tôi sẽ phản hồi sớm nhất có thể.
              </p>
              <ul className="contact-benefits">
                <li>💬 Phản hồi trong vòng 24h</li>
                <li>👩‍💻 Hỗ trợ kỹ thuật chuyên sâu</li>
                <li>⚡ Ưu tiên khách hàng Premium</li>
              </ul>
            </div>

            <div className="contact-form-wrapper">
              {submitted && (
                <div className="success-message">
                  <CheckCircle2 size={24} /> Đã gửi thành công! Cảm ơn bạn đã
                  liên hệ.
                </div>
              )}
              <form onSubmit={handleSubmit} className="contact-form-modern">
                <div className="form-group">
                  <label>Họ và tên *</label>
                  <input
                    name="name"
                    value={form.name}
                    onChange={handleChange}
                    required
                    placeholder="Nhập họ tên của bạn"
                  />
                </div>

                <div className="form-group">
                  <label>Email *</label>
                  <input
                    type="email"
                    name="email"
                    value={form.email}
                    onChange={handleChange}
                    required
                    placeholder="Địa chỉ email của bạn"
                  />
                </div>

                <div className="form-group">
                  <label>Số điện thoại</label>
                  <input
                    name="phone"
                    value={form.phone}
                    onChange={handleChange}
                    placeholder="Tuỳ chọn"
                  />
                </div>

                <div className="form-group">
                  <label>Nội dung hỗ trợ</label>
                  <textarea
                    name="notes"
                    rows="4"
                    value={form.notes}
                    onChange={handleChange}
                    placeholder="Mô tả chi tiết vấn đề bạn gặp phải..."
                  ></textarea>
                </div>

                <button type="submit" className="btn-submit-modern">
                  Gửi yêu cầu hỗ trợ
                </button>
              </form>
            </div>
          </div>
        </section>

        {/* CTA Footer */}
        <section className="cta-support">
          <div className="cta-inner">
            <h2>Luôn đồng hành cùng bạn</h2>
            <p>
              Đội ngũ LandingHub luôn sẵn sàng hỗ trợ 24/7 cho mọi khách hàng.
            </p>
            <button className="cta-btn">Trò chuyện ngay</button>
          </div>
        </section>
      </div>
    </Background>
  );
};

export default Support;
